monotoneCubic = (points) =&gt; {
  const xs = points.map((p) =&gt; p.x);
  const ys = points.map((p) =&gt; p.y);
  const n = points.length;

  const dx = [], dy = [], sl = [];
  for (let i = 0; i &lt; n - 1; i++) {
    dx.push(xs[i + 1] - xs[i]);
    dy.push(ys[i + 1] - ys[i]);
    sl.push(dy[i] / dx[i]);
  }

  const m = new Array(n);
  m[0] = sl[0];
  m[n - 1] = sl[n - 2];
  for (let i = 1; i &lt; n - 1; i++) {
    if (sl[i - 1] * sl[i] &lt;= 0) {
      m[i] = 0;
    } else {
      m[i] = (sl[i - 1] + sl[i]) / 2;
    }
  }

  for (let i = 0; i &lt; n - 1; i++) {
    if (sl[i] === 0) {
      m[i] = 0;
      m[i + 1] = 0;
      continue;
    }
    const alpha = m[i] / sl[i];
    const beta = m[i + 1] / sl[i];
    const squared = alpha * alpha + beta * beta;
    if (squared &gt; 9) {
      const tau = 3 / Math.sqrt(squared);
      m[i] = tau * alpha * sl[i];
      m[i + 1] = tau * beta * sl[i];
    }
  }

  return (x) =&gt; {
    if (x &lt;= xs[0]) return ys[0];
    if (x &gt;= xs[n - 1]) return ys[n - 1];

    let i = 0;
    while (i &lt; n - 2 && x &gt; xs[i + 1]) i++;

    const h = xs[i + 1] - xs[i];
    const t = (x - xs[i]) / h;
    const t2 = t * t;
    const t3 = t2 * t;

    return (2 * t3 - 3 * t2 + 1) * ys[i] + (t3 - 2 * t2 + t) * h * m[i] + (-2 * t3 + 3 * t2) * ys[i + 1] + (t3 - t2) * h * m[i + 1];
  };
}







































