stepData = {
  const K = 1;
  const dt = 0.01;
  const tMax = 10;
  const data = [];

  for (let t = 0; t &lt;= tMax + Tt; t += dt) {
    let y = 0;

    if (t &gt;= Tt) {
      const tau = t - Tt;

      if (systemType === "ns") {
        if (Math.abs(T1 - T2) &lt; 1e-6 && T1 &gt; 1e-6) {
          y = K * (1 - (1 + tau / T1) * Math.exp(-tau / T1));
        } else if (T1 &gt; 1e-6 && T2 &gt; 1e-6) {
          const a = T1 / (T1 - T2);
          const b = T2 / (T1 - T2);
          y = K * (1 - a * Math.exp(-tau / T1) + b * Math.exp(-tau / T2));
        } else if (T1 &gt; 1e-6) {
          y = K * (1 - Math.exp(-tau / T1));
        } else if (T2 &gt; 1e-6) {
          y = K * (1 - Math.exp(-tau / T2));
        } else {
          y = K;
        }
      } else if (systemType === "os") {
        const w = omega;
        const d = Damp;
        if (d &lt; 1) {
          const wd = w * Math.sqrt(1 - d * d);
          const phi = Math.acos(d);
          y = K * (1 - Math.exp(-d * w * tau) / Math.sqrt(1 - d * d) * Math.sin(wd * tau + phi));
        } else {
          y = K * (1 - (1 + w * tau) * Math.exp(-w * tau));
        }
      }
    }

    if (t &lt;= tMax) {
      data.push({t, y});
    }
  }

  return data;
}









